window.docContents[75].resolve({"/releases/#build-time-docstring-markdown":{"contents":"Breaking changes:\n\n* The constants Highlighted.WebAssets.marked and Highlighted.WebAssets.marked.map no longer exist, and verso-literate-html no longer writes marked.js.* The keys of Html.katexFonts now have the form fonts/..., relative to the KaTeX stylesheet, rather than katex/fonts/....* Verso.Genre.Manual.Markdown.HeaderMapping is now Verso.Markdown.HeaderMapping.* Verso.Genre.Blog.Traverse.renderMathJs no longer exists. The blog's page template loads the bundled KaTeX and math.js from -verso-data/katex/.\n\n","context":"Writing Documentation in Lean with Verso\u0009Release Notes\u0009Verso 4.36.0","header":"Offline Docstring Markdown","id":"/releases/#build-time-docstring-markdown"}});